import { writeFile } from 'node:fs/promises';
import { THEME_TOKENS } from '../src/shared/theme-tokens.ts';

const introduction =
  '# Theme token contract\n\nGenerated by `node scripts/theme-contract.mjs` from `src/shared/theme-tokens.ts`.\n\nSet these through `theme.dark`, `theme.light` or trusted `api.branding({ theme })`. Each name maps to\na CSS custom property with a `--` prefix. Names are added, never renamed. Values must be plain CSS\nwithout URLs, comments or declaration delimiters. Defaults live in `styles.css` and `theme-tokens.css`;\ncaption defaults also work in the standalone video renderer. Reduced-motion and forced-color rules\ncontinue to take precedence. Set background and foreground pairs together and check contrast.\n\n';
await writeFile(
  new URL('../docs/tokens.md', import.meta.url),
  introduction + THEME_TOKENS.map((name) => `- \`${name}\``).join('\n') + '\n',
);
await writeFile(
  new URL('../docs/formats/theme-tokens.json', import.meta.url),
  JSON.stringify({ version: 2, tokens: THEME_TOKENS }, null, 2) + '\n',
);
